bpmn:scriptTask.bpmn:script:
var cantidad = Number(execution.getVariable("recordatorios"));
execution.setVariable("recordatorios",
    java.lang.Integer.valueOf(cantidad + 1));
print("Recordatorio numero " + (cantidad + 1));

if (execution.getVariable("aulaVirtualReservada") == true) {
    execution.setVariable("aulaVirtualReservada", false);
    print("Aula virtual liberada");
}
